5	/**
6	 * Normalises a telephone number to E.164 form: keep a leading '+' and country code
7	 * when present, otherwise assume '+61' and drop a single leading '0' from the national
8	 * digits. Spaces, dashes and brackets are stripped; 8 to 15 digits must remain.
9	 */
10	final class E164 {
11	
12	    private E164() {
13	    }
14	
15	    static String normalize(String telephone) throws InvalidTelephoneException {
16	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
17	        String digits;
18	        if (cleaned.startsWith("+")) {
19	            digits = cleaned.substring(1);
20	        } else {
21	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
22	            digits = "61" + national;
23	        }
24	        if (!digits.matches("\\d{8,15}")) {
25	            throw new InvalidTelephoneException("Telephone cannot be formatted as E.164");
26	        }
27	        requireNationalLength(digits);
28	        return "+" + digits;
29	    }
30	
31	    /**
32	     * Enforce the national-number length required by the country code: '+61' needs 9
33	     * national digits, '+1' needs 10. Unknown country codes are left unchecked.
34	     */
35	    private static void requireNationalLength(String digits) throws InvalidTelephoneException {
